public class Main {static final Object first=new Object(),second=new Object();static void work(String name){synchronized(first){System.out.println(name+" locked first resource");synchronized(second){System.out.println(name+" locked second resource");}}}public static void main(String[] args){Thread a=new Thread(()->work("Thread A"));Thread b=new Thread(()->work("Thread B"));a.start();b.start();}}
